contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract: deposit some ETH via fallback, then attempt withdrawAll from an arbitrary caller
    // params:
    //   depositAmt - amount of wei this test contract will send to C to increase its balance
    //   callWithdrawAsSender - address from which withdrawAll is invoked (simulated by msg.sender of this external call)
    // NOTE: this function must be called by an EOA or contract having at least depositAmt balance.
    function runTest(uint depositAmt) public payable {
        // ensure this test contract has enough balance to send depositAmt
        require(msg.value == depositAmt, "send depositAmt as msg.value");

        // send depositAmt to c to increase its balance via fallback
        // fallback increments depositsCount in C and accepts Ether
        (bool sent,) = address(c).call{value: depositAmt}("");
        require(sent, "deposit failed");

        // record balance of c before withdrawAll
        uint balBefore = address(c).balance;

        // attempt to call withdrawAll as this caller (in P this will succeed only if caller==owner)
        // In P, non-owner cannot call withdrawAll (revert), so c's balance remains balBefore.
        // In mutant M, any caller can call withdrawAll and drain funds, so balance will decrease.
        // We call withdrawAll directly; if it reverts, the state remains unchanged and the call fails here.
        // We catch reverts by using low-level call to get a boolean instead of revert propagation.
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // observe balance after the attempt
        uint balAfter = address(c).balance;

        // General rule: after a withdrawAll attempt by an arbitrary caller, contract balance must not decrease
        // (i.e., only owner can cause balance to decrease). This holds for the original P but is violated by M.
        assert(balAfter >= balBefore);
    }

    // allow contract to receive ETH for paying depositAmt when calling runTest
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // attempt to call withdrawAll as caller by using low-level call to preserve msg.sender
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        reverted = !ok;
        // The rule: if the caller is not the recorded owner (c.owner()), then the call must revert.
        // Conversely, if caller equals c.owner(), the call must not revert. We express as equivalence.
        address owner = c.owner();
        assert(reverted == (caller != owner));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // Make the call as if from `caller` by using low-level call to forward msg.sender
        // We cannot change msg.sender here, so instead require that when run() is invoked
        // by a non-owner (unknown to test), withdrawAll should revert. To express this
        // as a general property over parameters, we call withdrawAll via c directly
        // and observe whether it reverted. The rule: if the caller argument is not equal
        // to the owner, the call must revert. Since we cannot read owner, we assert
        // that either the call reverted or caller equals tx.origin (i.e., caller could be owner).
        // However, we must not read internal owner; instead we express the general rule
        // as: if withdrawAll did not revert, then caller must be able to be the owner —
        // implemented as caller == address(this) because only the contract that deployed C
        // (owner) can be the owner in general. To keep the rule general and capture the mutant,
        // we instead require that withdrawAll can only succeed when called by the same address
        // as c.owner() — but owner() is public, so we can read it.

        // Single state-changing call on c as top-level statement:
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        // General rule: if the caller parameter is not equal to c.owner(), then the call must revert.
        // This captures that only the owner can call withdrawAll in the original contract,
        // and the mutant (which removes the require) would allow non-owners and thus violate this.
        assert(reverted || caller == c.owner());
    }
    receive() external payable { }
}

