        // Now call sendMoney routing through an attacker contract which will call back into c.withdrawAll if allowed
        // We fund the attacker so it can trigger any payable flows
        vm.deal(address(attacker), 0);

        // The attacker will attempt to call c.withdrawAll() after sendMoney returns by exploiting the removed onlyOwner
        // We call c.sendMoney with target = attacker and value = 0 so that attacker.receive() does not get ETH, but attacker
