pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to send and a boolean indicating whether the helper will revert on receive
    function testFuzz_property(uint256 amt, bool helperReverts) public {
        // keep amount reasonable but wide
        amt = bound(amt, 0, 1 ether);

        // deploy helper that either reverts on fallback or acts as benign receiver
        ReceiverHelper helper = new ReceiverHelper(helperReverts);

        // fund the contract with some Ether so sendMoney has balance to send
        vm.deal(address(this), 2 ether);
        // top up C
        payable(address(c)).transfer(1 ether);

        // ensure helper has no funds initially
        vm.deal(address(helper), 0);

        // act as the owner (setUp deployer is owner), call sendMoney to helper with amt
        // sendC may transfer amt; wrap call to observe whether it reverts
        bool ok;
        try c.sendMoney(address(helper), amt, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // The general invariant: when owner calls sendMoney to a callee that reverts on receive,
        // the call itself should revert (ok == false) and C's balance must remain unchanged.
        // For non-reverting callee, the call should succeed (ok == true) and C's balance should decrease by amt.
        uint256 bal = address(c).balance;

        if (helperReverts) {
            // if helper reverts, sendMoney should have reverted and contract balance unchanged at 1 ether
            assertTrue(!ok);
            assertTrue(bal == 1 ether);
        } else {
            // if helper does not revert, call should succeed and contract balance decreased by amt (limited by available funds)
            assertTrue(ok);
            uint256 expected = 1 ether;
            if (amt <= 1 ether) expected = 1 ether - amt;
            else expected = 0; // sending more than balance will transfer up to balance and may revert elsewhere, keep wide
            assertTrue(bal == expected);
        }
    }
}

// Helper that can optionally revert on fallback to simulate an adversarial callee
contract ReceiverHelper {
    bool public shouldRevert;
    constructor(bool _r) payable {
        shouldRevert = _r;
    }
    fallback() external payable {
        if (shouldRevert) revert("revert on receive");
    }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
}

