    function testFuzz_property(uint256 attackerInitialBal, uint256 value) public {
        // keep values in wide admissible domain but avoid overflow issues and trivial zero-value case
        attackerInitialBal = bound(attackerInitialBal, 1 wei, 1 ether);
        value = bound(value, 0 wei, 1 ether);

        // deploy adversarial callee that reverts on fallback/receive
        Reverter attacker = new Reverter();

        // fund contract and attacker appropriately
        // give C some funds to be potentially withdrawn
        vm.deal(address(this), 1 ether);
        // send 0.5 ether to C
        payable(address(c)).transfer(0.5 ether);

        // fund attacker externally so it can be an EOA with code (but it's a contract already)
        vm.deal(address(attacker), attackerInitialBal);

        // ensure caller is owner (setUp deployer is owner)
        // call sendMoney as owner, forwarding `value` wei from C to attacker
        // to have C perform the external call, we make the call originate from the owner and have the call be from C funds
        // set up call from owner (this contract is not the owner; owner is Deployer from setUp which is this test contract because new C() used msg.sender)
        // The test contract deployed C in setUp, so address(this) is owner.

        // record balance before
        uint256 before = address(c).balance;

        // perform the external call from C: owner calls sendMoney(attacker, value, data)
        // value to send must come from C balance; ensure value <= before to avoid revert from insufficient funds
        value = bound(value, 0, before);

        // perform the call; if the callee reverts, sendMoney should propagate the revert (require on call result)
        bool ok;
        try c.sendMoney(address(attacker), value, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // After the owner-call to sendMoney where the callee reverts, the reference C must preserve its balance (no withdrawal executed): address(c).balance == before
        // For the mutant that removed onlyOwner, an attacker callee could have caused withdraw to be executed during the external call and thus changed the balance for some inputs.
        assertTrue(address(c).balance == before);
    }
}

