        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositor funds the contract, caller tries to withdraw
    function run(address payable depositor, address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        // preconditions for meaningful scenario
        require(depositor != address(0));
        require(caller != address(0));
        require(depositor != caller);
        // this contract must hold enough ETH to forward depositAmount
        // caller may be any external account simulated by the tester; we just need to send ETH from this contract
        require(address(this).balance >= depositAmount);

        // Fund contract C by invoking its fallback with depositAmount from this contract
        (bool sent,) = address(c).call{value: depositAmount}("\x00");
        require(sent);

        uint256 before = address(c).balance;

        // Attempt withdrawal invoked as 'caller' is simulated by an external tester in the harness.
        // We express the decision: call withdraw from c; the harness should perform the call from 'caller'.
        // To stay within constraints, perform the call normally; the harness will manage tx.sender.
        c.withdraw(withdrawAmount);

        uint256 after = address(c).balance;

        // General rule: if caller is not the owner, contract balance must not decrease.
        // On the original contract P this holds (onlyOwner prevents non-owner withdraw),
        // but the mutant M (removed require) would allow a non-owner to reduce the balance.
        assert(!(depositor != caller) || after == before);
    }

    // Allow this contract to receive ETH for funding deposits
    receive() external payable {}
}

